const stats = $('Kullanıcı İstatistikleri').first().json;
const apps  = $('Top Uygulamalar').all();
const fmt = (s) => `${Math.floor(s/3600)}s ${Math.floor((s%3600)/60)}dk`;

let appLines = apps.map(a => `   ${a.json.app_name.padEnd(15)} ${fmt(a.json.sn)}`).join('\n');

const msg = `📊 Günlük Özet\n\n⏱ Aktif: ${fmt(stats.aktif || 0)}\n😴 Boşta: ${fmt(stats.bosta || 0)}\n\n💻 Top Uygulamalar:\n${appLines || '   Veri yok'}`;

return [{ json: { text: msg, chat_id: 'TELEGRAM_CHAT_ID_BURAYA' } }];
